/* waX VPN site - real v0.1.9 product screenshots (verification-gate captures).
   Stored as WebP data URIs so the GitHub Pages text-only publish flow can ship them;
   lazy-injected near the viewport to keep first paint light. Do not edit by hand. */
(function(){
"use strict";
var SHOTS={
disconnected:"data:image/webp;base64,",
connected:"data:image/webp;base64,",
profiles:"data:image/webp;base64,",
features:"data:image/webp;base64,",
warp:"data:image/webp;base64,",
about:"data:image/webp;base64,",
settings_load_warning:"data:image/webp;base64,",
settings_save_warning:"data:image/webp;base64,",
installed:"data:image/webp;base64,",
};
function inject(el){
  var key=el.getAttribute('data-shot');
  if(!key||!SHOTS[key])return;
  el.addEventListener('load',function(){el.classList.add('on');},{once:true});
  el.src=SHOTS[key];
  el.removeAttribute('data-shot');
}
function init(){
  var imgs=[].slice.call(document.querySelectorAll('img[data-shot]'));
  if(!imgs.length)return;
  if(!('IntersectionObserver' in window)){imgs.forEach(inject);return;}
  var io=new IntersectionObserver(function(entries){
    entries.forEach(function(en){if(en.isIntersecting){inject(en.target);io.unobserve(en.target);}});
  },{rootMargin:'500px 0px'});
  imgs.forEach(function(el){io.observe(el);});
}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}
})();
